import { useState } from 'react';
import { RefreshCw, Save, Home, Layers, Settings, Smartphone, Moon, Sun, Server } from 'lucide-react';
import { NavItem } from '@/components/ui';
import { useBoxController } from '@/hooks/useBoxController';
import { useTheme } from '@/hooks/useTheme';
import { TabHome } from '@/tabs/TabHome';
import { TabProxies } from '@/tabs/TabProxies';
import { TabApps } from '@/tabs/TabApps';
import { TabAdvanced } from '@/tabs/TabAdvanced';
import '@/index.css';

export default function App() {
  const [activeTab, setActiveTab] = useState('home');
  const { theme, isDark, cycleTheme } = useTheme();
  const {
    loading,
    status,
    config,
    appList,
    actionLoading,
    hasChanges,
    handleServiceAction,
    handleToggle,
    handleChange,
    handleSaveAndApply,
    handleToggleAutoStart,
  } = useBoxController();

  if (loading) {
    return (
      <div className={`flex min-h-dvh items-center justify-center ${isDark ? 'bg-slate-950' : 'bg-slate-50'}`}>
        <div className="animate-spin text-indigo-500"><RefreshCw size={28} /></div>
      </div>
    );
  }

  return (
    <div className={`mx-auto h-dvh max-w-md overflow-hidden font-sans shadow-2xl transition-colors duration-300 ${isDark ? 'bg-slate-950 text-slate-200' : 'bg-slate-50 text-slate-800'} relative`}>
      {/* Top Navigation */}
      <header className="bg-white/80 dark:bg-slate-900/80 backdrop-blur-md border-b border-slate-200 dark:border-slate-800 sticky top-0 z-30 transition-colors">
        <div className="px-5 py-3.5 flex items-center justify-between">
          <div className="flex items-center space-x-2.5">
            <div className={`w-2.5 h-2.5 rounded-full ${status.running ? 'bg-emerald-500 shadow-[0_0_8px_rgba(16,185,129,0.5)] animate-pulse' : 'bg-rose-500'}`} />
            <h1 className="text-lg font-bold text-slate-900 dark:text-slate-100 tracking-tight transition-colors">Box 控制台</h1>
            <div className="text-xs font-semibold text-slate-500 dark:text-slate-400 bg-slate-100 dark:bg-slate-800 px-2 py-0.5 rounded-md flex items-center transition-colors">
              {status.running ? `PID: ${status.pid}` : 'STOPPED'}
            </div>
          </div>
          <button onClick={cycleTheme} className="p-1.5 rounded-full bg-slate-100 dark:bg-slate-800 text-slate-500 dark:text-slate-400 hover:bg-slate-200 dark:hover:bg-slate-700 transition-colors" title="切换主题">
            {theme === 'system' ? <Smartphone size={16} /> : theme === 'dark' ? <Moon size={16} /> : <Sun size={16} />}
          </button>
        </div>
      </header>

      {/* Main Content Area */}
      <main className="h-[calc(100dvh-53px)] overflow-y-auto pb-32 pt-2 scrollbar-hide">
        {activeTab === 'home' && <TabHome status={status} config={config} handleServiceAction={handleServiceAction} actionLoading={actionLoading} handleChange={handleChange} handleToggle={handleToggle} handleToggleAutoStart={handleToggleAutoStart} />}
        {activeTab === 'proxies' && <TabProxies status={status} />}
        {activeTab === 'apps' && <TabApps config={config} handleToggle={handleToggle} handleChange={handleChange} appList={appList} />}
        {activeTab === 'advanced' && <TabAdvanced status={status} config={config} handleToggle={handleToggle} handleChange={handleChange} />}
      </main>

      {/* Floating Save Button */}
      {hasChanges && (
        <div className="absolute bottom-16 right-6 z-40 animate-in slide-in-from-bottom-4 zoom-in duration-300">
          <button
            onClick={handleSaveAndApply}
            disabled={actionLoading === 'save'}
            className="bg-indigo-600 hover:bg-indigo-700 text-white px-5 py-3.5 rounded-full shadow-[0_4px_16px_rgba(79,70,229,0.4)] flex items-center space-x-2 font-bold active:scale-95 transition-all"
          >
            {actionLoading === 'save' ? <RefreshCw size={20} className="animate-spin" /> : <Save size={20} />}
            <span>{actionLoading === 'save' ? '应用中...' : '保存'}</span>
          </button>
        </div>
      )}

      {/* Bottom Navigation */}
      <nav className="absolute bottom-0 w-full bg-white dark:bg-slate-900 border-t border-slate-200 dark:border-slate-800 px-6 py-2 pb-safe flex justify-between items-center z-30 transition-colors">
        <NavItem icon={<Home size={24} />} label="首页" active={activeTab === 'home'} onClick={() => setActiveTab('home')} />
        <NavItem icon={<Server size={24} />} label="代理" active={activeTab === 'proxies'} onClick={() => setActiveTab('proxies')} />
        <NavItem icon={<Layers size={24} />} label="分流" active={activeTab === 'apps'} onClick={() => setActiveTab('apps')} />
        <NavItem icon={<Settings size={24} />} label="高级" active={activeTab === 'advanced'} onClick={() => setActiveTab('advanced')} />
      </nav>
    </div>
  );
}

akasha-make.text:
NAME=akashaProxy
CC ?= clang
.PHONY: all pack download-dashboard download-mihomo build-webui clean check-deps build-tools default download build-ruleconverter download-geodata
all: default

default: check-deps clean init download pack

check-deps:
	@command -v curl >/dev/null 2>&1 || { echo >&2 "[ERROR] curl is not installed. Please install curl."; exit 1; }
	@command -v unzip >/dev/null 2>&1 || { echo >&2 "[ERROR] unzip is not installed. Please install unzip."; exit 1; }
	@command -v pnpm >/dev/null 2>&1 || { echo >&2 "[ERROR] pnpm is not installed. Please install pnpm."; exit 1; }
	@command -v go >/dev/null 2>&1 || { echo >&2 "[ERROR] go is not installed. Please install go."; exit 1; }
	@command -v upx >/dev/null 2>&1 || { echo >&2 "[ERROR] upx is not installed. Please install upx."; exit 1; }

init:
	@git submodule update --init --recursive
	@mkdir -p tmp
	@cp -rf module/* tmp/

download: download-mihomo download-dashboard download-geodata

pack: build-tools build-webui build-ruleconverter
	echo "id=akashaProxy\nname=akashaProxy\nversion="$(shell git rev-parse --short HEAD)"\nversionCode="$(shell git log -1 --format=%ct)"\nauthor=akashaProxy developer\ndescription=akasha terminal transparent proxy module that supports tproxy and tun and adds many easy-to-use features. Compatible with Magisk/KernelSU">tmp/module.prop
	cd tmp && zip -r ../$(NAME).zip *
	@echo "module pack successfully"

download-geodata:
	curl --connect-timeout 5 --progress-bar -L -o tmp/src/GeoSite.dat \
	"https://github.com/Loyalsoldier/v2ray-rules-dat/releases/latest/download/geosite.dat"
	curl --connect-timeout 5 --progress-bar -L -o tmp/src/GeoIP.dat \
	"https://github.com/Loyalsoldier/v2ray-rules-dat/releases/latest/download/geoip.dat"

download-mihomo:
	@mkdir -p tmp/bin
	remote_mihomo_ver=$$(curl --connect-timeout 5 -L "https://github.com/MetaCubeX/mihomo/releases/latest/download/version.txt") && \
	curl --connect-timeout 5 --progress-bar -L -o tmp/bin/mihomo-android-arm64-v8.gz \
	"https://github.com/MetaCubeX/mihomo/releases/latest/download/mihomo-android-arm64-v8-$${remote_mihomo_ver}.gz"
	@echo "mihomo download successfully"

download-dashboard:
	@mkdir -p tmp/src/zashboard
	curl --connect-timeout 5 --progress-bar -L -o tmp/src/zashboard/dist-no-fonts.zip \
	"https://github.com/Zephyruso/zashboard/releases/latest/download/dist-no-fonts.zip"
	unzip -o tmp/src/zashboard/dist-no-fonts.zip -d tmp/src/zashboard/
	mv -f tmp/src/zashboard/dist/* tmp/src/zashboard/
	rm -rf tmp/src/zashboard/dist
	rm -rf tmp/src/zashboard/dist-no-fonts.zip
	@echo "dashboard download successfully"

build-webui:
	cd webui && pnpm i
	cd webui && pnpm build
	mv -f ./webui/out ./tmp/webroot
	@echo "webui build successfully"

build-tools:
	cd yamlcli && go mod tidy
	cd yamlcli && CGO_ENABLED=0 GOOS=android GOARCH=arm64 go build -trimpath -ldflags="-s -w" -buildvcs=false -o ../tmp/src/bin/yamlcli
	upx tmp/src/bin/yamlcli
	@echo "yamlcli build successfully"

build-ruleconverter:
	cd plugins/ruleconverter && go mod tidy
	cd plugins/ruleconverter && CGO_ENABLED=0 GOOS=android GOARCH=arm64 go build -trimpath -ldflags="-s -w" -buildvcs=false -o ../../tmp/src/plugins/ruleconverter/bin/ruleconverter
	upx tmp/src/plugins/ruleconverter/bin/ruleconverter
	@echo "ruleconverter build successfully"

clean:
	rm -rf tmp
	rm -rf $(NAME).zip

